{
  "status": "SUPPORTED",
  "task_summary": "Identify compatible fastening components, complete the fastening at the marked workbench location, and leave reusable equipment safely on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "REGION",
        "function": "The specific workbench location where the fastening operation is to be performed.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "workbench surface",
          "marked workbench location",
          "assembly fixture"
        ],
        "required_properties": []
      },
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "A physical item compatible with the fastening target that can be used to complete the fastening.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "screw",
          "bolt",
          "nut",
          "washer",
          "clip",
          "pin",
          "fastener"
        ],
        "required_properties": [
          "compatible with fastening target"
        ]
      },
      {
