          "screwdriver",
          "wrench",
          "hammer",
          "drill",
          "pliers",
          "assembly tool"
        ],
        "required_properties": [
          "capable of applying fastening component"
        ]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The physical surface where reusable equipment is to be left after the task.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "workbench top",
          "table surface",
          "assembly table"
        ],
        "required_properties": []
      }
    ],
    "functional_relations": [
      {
        "subject_role": "fastening_component",
        "relation": "compatible with",
        "object_role": "fastening_target",
        "required": true
      },
      {
        "subject_role": "fastening_tool",
        "relation": "capable of applying",
        "object_role": "fastening_component",
        "required": true
      },
      {
        "subject_role": "fastening_tool",
        "relation": "applied to",
        "object_role": "fastening_target",
        "required": true
      }
    ],
