        "operation_count": 1,
        "reuse_policy": "DEDICATED_PER_TARGET"
      },
      {
        "id": "complete_fastening",
        "operation": "apply fastening component to target",
        "source_role": "fastening_tool",
        "target_role": "fastening_target",
        "operation_count": 1,
        "reuse_policy": "DEDICATED_PER_TARGET"
      },
      {
        "id": "place_tool",
        "operation": "place fastening tool on workbench surface",
        "source_role": "fastening_tool",
        "target_role": "workbench_surface",
        "operation_count": 1,
        "reuse_policy": "DEDICATED_PER_TARGET"
      }
    ]
  },
